const BASE=original.id,PK=BASE+':content',SK=BASE+':session';let project=clone(original),session=null,storage=true,view=routeView(),gameId=null,itemIndex=0,last=null,scratch={},flashIndex=0,flashBack=false,search='',editorInstance=null,editorSnapshot='',notice='',clock=null,clockLeft=0,clockEnd=0,gameFilter='all',arcadeRun=null,pendingRun=false,homeOrgan='kidneys',homeFactIndex=0,homeFactFlipped=false;
